-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":1,"title":"أهمية القراءة في حياتنا","passage":"تساعد القراءة المتأنية على زيادة الحصيلة اللغوية وفهم الأفكار ومراجعة الحجج، وتتحسن جودتها بطرح الأسئلة لا بعدد الصفحات فقط. في مثال مستقل تقرأ طالبة فقرة عن المكتبات ثم تسجل فكرتها الرئيسة وشاهدًا يوضحها وسؤالًا لم تجب عنه الفقرة.","question":"ما السلوك الذي يدل على فهم قرائي نشط؟","correct":"استخراج فكرة وشاهد وسؤال","wrong":["عد الصفحات فقط","نسخ عنوان الفقرة","إخفاء الكلمات الجديدة"],"practice":"اقرأ فقرة من مصدر مأذون، واكتب فكرتها وحجتين من ألفاظ الكاتب وسؤالًا مفتوحًا.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":2,"title":"معنى الإسلام","passage":"يتناول درس معنى الإسلام من منظور لغوي وتربوي وفق المنهج المعتمد، وينبغي التمييز بين شرح مفهوم ديني عام وبين نقل نص قرآني أو حديث يحتاج توثيقًا دقيقًا. في موقف تربوي مستقل يتعلم طلاب التعامل بأمانة واحترام وتعاون، دون نسب قصتهم إلى مصدر ديني.","question":"ما الإجراء الصحيح قبل نقل آية أو حديث في درس ديني؟","correct":"الرجوع إلى نص ومصدر صحيحين","wrong":["صياغة معنى على أنه آية","اعتماد مقولة غير معروفة","اختلاق رواية"],"practice":"اكتب فقرة عن قيمة الأمانة مع إحالة دقيقة إلى مصدر ديني معتمد يراجعه المعلم.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":3,"title":"لمحة عن الأدب العربي","passage":"يتنوع الأدب العربي عبر العصور والأقاليم والأجناس بين الشعر والسرد والخطابة وغيرها، ولا يمكن اختزاله في كاتب أو زمن واحد. يُميّز القارئ بين الغرض الأدبي والبنية الفنية وسياق النص؛ في نموذج مستقل يصف راو رحلة مدرسية بصياغة نثرية متخيلة.","question":"ما نوع النص الذي يسرد أحداث رحلة في فقرات؟","correct":"نص سردي نثري","wrong":["قصيدة عمودية حتمًا","خطبة دينية بالضرورة","وزن عروضي"],"practice":"صمم خريطة موجزة لأربعة أجناس أدبية عربية مع مثال موثق لكل جنس.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":4,"title":"السودان أمي وأبي (قصيدة)","passage":"عنوان «السودان أمي وأبي» يحيل إلى قصيدة ينبغي الرجوع إلى نصها المدرسي واسم شاعرها المحقق قبل نقل أي بيت أو تفسير صورة مخصوصة. في مثال أصلي يكتب متعلم عن ارتباطه بمدينته وذكرياته الأسرية، وهو نثر تدريبي غير منسوب للقصيدة.","question":"ما الدليل المقبول على صورة الوطن في القصيدة؟","correct":"شاهد من أبياتها الموثقة","wrong":["العنوان وحده","بيت مبتكر من الطالب","حكاية شاعر غير مثبتة"],"practice":"اقرأ نسخة مأذونة من القصيدة واستخرج صورة واحدة وفسر علاقة المخاطب بالوطن.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":5,"title":"القراءة المفيدة","passage":"تكون القراءة مفيدة عندما تُختار المادة بحسب هدف واضح ويُفهم مضمونها وتُراجع الأدلة فيها؛ لا تكفي السرعة دون استيعاب. مثال مستقل يبحث طالب عن أثر تنظيم الوقت ثم يقارن بين رأيين ويحدد بيانات كل مصدر قبل كتابة خلاصة.","question":"ما الذي يزيد فائدة القراءة في المثال؟","correct":"ربط القراءة بهدف ومراجعة الأدلة","wrong":["اختيار عنوان جذاب فقط","حفظ رقم الصفحة","تجنب المقارنة"],"practice":"ضع خطة قراءة أسبوعية قصيرة مع هدف وسؤال ووسيلة لمراجعة فهمك.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":6,"title":"من مصادر المعرفة (المكتبة)","passage":"تتيح المكتبة الوصول إلى كتب ومجلات ومراجع رقمية تختلف في موثوقيتها وطريقة تنظيمها، وتفيد الفهارس في تحديد المؤلف والعنوان والموضوع. في موقف أصلي تبحث طالبة عن معجم، فتستخدم رقم التصنيف ثم تتثبت من طبعة الكتاب.","question":"ما الأداة التي تساعد في العثور على كتاب في المكتبة؟","correct":"الفهرس والتصنيف","wrong":["لون الغلاف فقط","الاعتماد على المصادفة","عدد المقاعد"],"practice":"اكتب إرشادًا من ست خطوات للبحث عن مصدر وحفظ بيانات الاستشهاد به.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":7,"title":"قيم وأخلاق (قصيدة)","passage":"تتطلب قراءة قصيدة في القيم والأخلاق تحديد كلمات الفعل والمخاطب والصور من الأبيات الصحيحة، دون خلق موعظة ونسبتها إلى شاعر غير متحقق. في مشهد مستقل يعيد طالب كتابًا استعاره في الوقت المحدد ويعتذر عن تأخر سابق؛ هذا نثر من ضاديوم.","question":"كيف يُثبت المتعلم القيمة الأخلاقية في قصيدة؟","correct":"بتفسير ألفاظ وأفعال من النص الصحيح","wrong":["الاعتماد على عنوان عام","نسبة بيت مختلق","استخدام رأي خارج السياق"],"practice":"اختر شاهدًا مأذونًا من القصيدة يعبّر عن قيمة، واشرح أثر الأسلوب.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":8,"title":"الوقت هو الحياة","passage":"يمكن قراءة موضوع الوقت عبر تحديد العادات والأولويات والنتائج، مع التمييز بين المبدأ الإرشادي وادعاء علمي يحتاج مصدرًا. في مثال مستقل يخصص فريق وقتًا للقراءة والحركة والراحة، ثم يراجع مدى واقعية الخطة دون إلزام الجميع بجدول واحد.","question":"ما الخطوة الأهم عند وضع خطة وقت شخصية؟","correct":"تحديد الأولويات والموارد والراحة","wrong":["حذف النوم","تقليد الآخرين بلا تعديل","الاعتماد على النية فقط"],"practice":"اكتب فقرة إقناعية عن إدارة الوقت تذكر فائدة وحدًّا عمليًا.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":9,"title":"ما لم تنله زرقاء اليمامة (قصيدة)","passage":"يحيل عنوان «ما لم تنله زرقاء اليمامة» إلى نص شعري محدد يتطلب التحقق من الشاعر والأبيات والمصادر قبل توظيف الرمز أو رواية تاريخية عنه. مثال مستقل يتصور متعلم مستقبل مدينته بعد تغيرات اجتماعية؛ هذا التدريب لا يمثل أبيات القصيدة.","question":"ما الذي يحدد وظيفة الإشارة التراثية في القصيدة؟","correct":"وجودها وسياقها في النص الموثق","wrong":["عنوان القصيدة وحده","رواية بلا مصدر","اختلاق بيت"],"practice":"حدد إشارة أو رمزًا فعليًا في النص المدرسي، وفسر علاقته بالفكرة مع مصدر واضح.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":10,"title":"الذكاء الاصطناعي","passage":"يساعد الذكاء الاصطناعي في تلخيص نصوص وتوليد مقترحات وتصنيف أمثلة، لكنه قد يخطئ أو يختلق مراجع؛ لذلك ينبغي مراجعة مخرجاته وإبقاء القرار التربوي للبشر. في موقف مستقل يقارن طالب ملخصًا مولدًا بالنص الأصلي فيكتشف معلومة غير موجودة.","question":"ما السلوك المسؤول عند استعمال ملخص مولد؟","correct":"مقارنته بالمصدر وتصحيح الأخطاء","wrong":["اعتباره صحيحًا دائمًا","نسبته للمؤلف الأصلي","إخفاء استخدام الأداة"],"practice":"اكتب فقرة توعوية عن فائدة وحدّ ومثال تحقق في أدوات الذكاء الاصطناعي.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":11,"title":"الاعتماد على الذات","passage":"يرتبط الاعتماد على الذات بالمبادرة وتنظيم المهام والاعتراف بالحاجة إلى المساعدة عند الضرورة؛ ولا يعني رفض التعاون. في مثال مستقل يحاول متعلم حل تمرين أولًا، ثم يسأل المعلم عن خطوة لم يفهمها ويعود لإتمام العمل.","question":"أي تصرف يجمع المبادرة والتعلم المسؤول؟","correct":"المحاولة أولًا وطلب المساعدة عند الحاجة","wrong":["رفض كل سؤال","إلقاء العمل على الزميل","إخفاء الخطأ"],"practice":"اكتب موقفًا متخيلًا يوضح كيف تساعد المبادرة والمساندة معًا في إنجاز مهمة.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":12,"title":"القصة ومراحل تطورها","passage":"تطورت أشكال القصة العربية وتقنياتها عبر سياقات تاريخية متعددة مع تغير الطباعة والجمهور والكتابة، ولا يصح رد تطورها إلى سبب واحد أو تاريخ دون مرجع. مثال مستقل يحكي راو حدثًا خطيًا ثم يعيده باستخدام الاسترجاع لإظهار اختلاف البناء.","question":"ما التقنية عندما يعود السرد إلى حدث سبق زمن الحكاية؟","correct":"الاسترجاع","wrong":["حذف الراوي","القافية","المبتدأ المؤخر"],"practice":"قارن بنية قصتين موثقتين من فترتين مختلفتين مع شاهد على الراوي والزمن.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":13,"title":"تبادلية (قصيدة)","passage":"تحتاج قصيدة «تبادلية» إلى نسخة أصلية موثقة لمعرفة المتكلم والمخاطب وصور التفاعل فيها، ولا يجوز اختلاق معنى تفصيلي من العنوان وحده. في مثال مستقل يتبادل شخصان رسائل تعاون بين مدرستين؛ وهو تدريب على العلاقة بين الأصوات لا أبيات شعرية.","question":"كيف يحدد القارئ معنى التبادل في قصيدة؟","correct":"من ضمائر المتكلمين والأفعال والسياق الصحيح","wrong":["العنوان وحده","تخمين النهاية","بيت مولد"],"practice":"استخرج من النص المقرر انتقالًا بين صوتين أو فكرتين إن وجد، مع توثيق.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":14,"title":"التعامل مع الناس فن","passage":"يشمل التواصل الفعال حسن الاستماع والوضوح واحترام الاختلاف وتحديد التوقعات؛ وقد يؤدي سوء فهم لفظ واحد إلى نزاع إذا لم يُطلب التوضيح. في مشهد مستقل يسأل طالب زميله عما قصد بكلمة ملتبسة ثم يعيد صياغة طلبه بأسلوب مهذب.","question":"ما التصرف الذي يمنع سوء الفهم في المثال؟","correct":"طلب التوضيح وإعادة صياغة المعنى","wrong":["افتراض النية السيئة","مقاطعة الآخرين","تكرار الاتهام"],"practice":"اكتب حوارًا قصيرًا يبين الاستماع الفعال والتوصل إلى اتفاق واضح.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":15,"title":"عنترة في ذاكرة التاريخ","passage":"يدرس عنترة بن شداد من خلال المصادر التاريخية والأدبية مع التمييز بين الشواهد الموثقة والروايات المتأخرة أو الحكايات الشعبية. لا يجوز خلق قول أو مغامرة ونسبتها إلى شخص تاريخي. مثال مستقل يقارن قارئ بين مصدر تراثي وشرح مدرسي.","question":"كيف نتجنب الخلط بين التاريخ والأسطورة في السيرة؟","correct":"مقارنة مصادر موثقة وتحديد طبيعة الرواية","wrong":["الاعتماد على فيلم فقط","الاقتباس المخترع","تاريخ غير موثوق"],"practice":"اكتب بطاقة عن نص من شعر عنترة مع التحقق من نسبته ومصدره.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":16,"title":"التمر","passage":"يمكن تناول التمر غذائيًا وزراعيًا وثقافيًا مع التمييز بين ما هو معلومات عامة وما يحتاج بيانات محلية حديثة؛ ولا يصح اختلاق نسب إنتاج أو نصيحة علاجية. في نموذج مستقل يزور طالب سوقًا ويسأل عن أصناف التمر وطرق حفظها من جهة موثوقة.","question":"ما الذي يلزم لتقرير عن إنتاج التمر في بلد؟","correct":"بيانات مؤرخة من مصدر رسمي","wrong":["تخمين الكمية","حكاية عابرة","لون الصور"],"practice":"اكتب وصفًا معلوماتيًا للتمر يضم صفات ظاهرة وفائدتين اجتماعيتين دون وصف علاج.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":17,"title":"كيف يعود السودان أخضرًا","passage":"تتصل استعادة الغطاء النباتي بإدارة المياه والتربة والمناخ والموارد المحلية، ولا يوجد إجراء واحد ينجح في كل منطقة. في مثال مستقل يناقش فريق مدرسي زرع أنواع مناسبة تحت إشراف بيئي مع قياس بقائها وتحديد مخاطر الجفاف.","question":"ما الذي يجب فحصه قبل مشروع تشجير؟","correct":"المناخ والماء والتربة وملاءمة الأنواع","wrong":["اختيار أي نوع دون بيانات","اختلاق نجاح","إلغاء المتابعة"],"practice":"اقترح مبادرة خضراء بمؤشرين قابلين للقياس ومصدر بيئي مناسب.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":18,"title":"بطل من شرق بلادي (قصيدة)","passage":"عنوان «بطل من شرق بلادي» يدل على نص شعري ينبغي التثبت من صاحبه وهويّة الشخصية الموصوفة فيه قبل نسبة أفعال أو أحداث تاريخية. في مثال مستقل يروي طالب فعل مساعدة قام به متطوع من منطقته؛ هو نموذج تربوي غير مقتبس من القصيدة.","question":"ما الدليل على صورة البطولة في النص؟","correct":"سلوك أو وصف مثبت في الأبيات الصحيحة","wrong":["تخمين الشخصية من العنوان","حكاية مجهولة","بيت مختلق"],"practice":"حلل شاهدًا مأذونًا من القصيدة واكتب وصفًا للبطل ملتزمًا حدود النص.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":19,"title":"حقوق الإنسان","passage":"تشمل حقوق الإنسان مبادئ الكرامة وعدم التمييز والسلامة والحق في التعليم وفق مصادر حقوقية معتبرة، ويجب الفصل بين المبدأ العام وتفاصيل قانون معين. في مثال مستقل تضع مدرسة آلية إنصاف للطلاب تسمح بسماع الاعتراضات دون كشف بياناتهم.","question":"ما الذي يدعم معاملة منصفة للطلاب؟","correct":"معايير معلنة وحق في المراجعة واحترام الكرامة","wrong":["قاعدة سرية","تعميم على الأفراد","إخفاء الشكوى"],"practice":"اكتب فقرة تقارن قيمة حقوقية بوضع مدرسي وتوثق المبدأ من جهة رسمية.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":20,"title":"الطلاب ومهارات المستقبل","passage":"قد تحتاج مهارات المستقبل إلى التفكير النقدي والتواصل والتعلم المستمر وحل المشكلات، ولا يثبت إعلان وظيفة واحدة توقعًا قاطعًا لسوق العمل. في مثال مستقل يستخدم طلاب جدولًا لتوزيع أدوار مشروع ويفحصون مصادر البيانات قبل العرض.","question":"ما المهارة التي تظهر عند فحص مصادر المعلومات؟","correct":"التفكير النقدي","wrong":["الحفظ الآلي فقط","الاعتماد على الشائعات","إلغاء التعاون"],"practice":"ضع خطة قصيرة لتطوير مهارتين مع نشاط ومؤشر تقييم.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":21,"title":"معنى البطولة (قصيدة)","passage":"ينبغي فهم البطولة في النص الشعري من أفعال الشخصيات وصورها والمخاطبين كما يرد في الأبيات الصحيحة، لا من مفهوم واحد يفرضه القارئ مسبقًا. نموذج مستقل يصور إنسانًا يعيد كتابًا ضائعًا لصاحبه، وهو تدريب نثري لا قصيدة.","question":"ما الطريق الصحيح لتفسير معنى البطولة في قصيدة؟","correct":"تحليل شواهد صحيحة من النص مع السياق","wrong":["إعطاء حكم قبل القراءة","اختلاق حادثة","العنوان وحده"],"practice":"ناقش شاهدًا واحدًا من القصيدة يبرز قيمة محددة وبين كيف دعمها الأسلوب.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":22,"title":"المسلمون وتحديات العصر","passage":"تتناول قراءة تحديات المجتمعات المسلمة قضايا متعددة قد تشمل التعليم والتقنية والاقتصاد والتواصل، ويجب عرضها بدقة واحترام تنوع التجارب بدل تعميم حالة واحدة. في مثال مستقل يخطط متعلمون لخدمة قراءة مجتمعية ويقيسون مدى الوصول إليها.","question":"ما الضابط المناسب عند تحليل تحدٍّ يواجه مجتمعات مختلفة؟","correct":"معلومات موثوقة وتجنب التعميم","wrong":["تخمين السبب للجميع","إلغاء الفروق","نسبة قول ديني غير متحقق"],"practice":"اكتب تحليلًا لتحدٍّ تعليمي واحد مع مصدر وحل مقترح وحدوده.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":23,"title":"تعليم المرأة","passage":"تتعلق فرص تعليم النساء والفتيات بالإتاحة والسلامة والجودة والحقوق والظروف الاجتماعية، ولا يصح تعميم تجربة فردية على بلد بأكمله. في نموذج مستقل تنظم مدرسة برنامجًا تطوعيًا للقراءة يتيح المشاركة وفق معايير واضحة وآمنة للجميع.","question":"ما الإجراء الذي يدعم فرصة تعليم عادلة في المثال؟","correct":"إتاحة المشاركة وفق قواعد شفافة وآمنة","wrong":["الإقصاء دون سبب","منع السؤال","إخفاء الشروط"],"practice":"اكتب فقرة حجاجية عن أهمية تعلم الفتيات مع شاهد موثق واحترام السياق.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":24,"title":"لمحة عن المسرح السوداني","passage":"للمسرح السوداني أعمال وتجارب متنوعة تتطلب توثيق أسماء المؤلفين والعروض وتواريخها من مراجع موثوقة، ولا يجوز اختراع مسرحية أو تاريخ عرض. مثال مستقل يجري حوار بين شخصيتين تناقشان فكرة نشاط قراءة من دون ادعاء نسبته لأي مسرحي.","question":"ما العناصر التي يبرزها التحليل الدرامي؟","correct":"الحوار والفعل وتحول المواقف","wrong":["التقطيع العروضي فقط","اسم الجمهور وحده","عدد الأسطر"],"practice":"اختر مسرحية سودانية موثقة وأعد بطاقة عن مؤلفها وموضوعها وعنصر فني.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":25,"title":"الحب الخالد قيس وليلى (قصيدة)","passage":"تتعدد الروايات الأدبية حول قيس وليلى ويحتاج توثيق الأبيات والمصادر إلى تدقيق لأن شيوع قصة لا يثبت كل قول منسوب إلى شخصياتها. مثال مستقل يكتب راو رسالة تقدير دون نسبتها لشاعر تراثي، ويستخدم لفهم خطاب العاطفة.","question":"ما أول خطوة لتوثيق بيت منسوب لقيس؟","correct":"الرجوع إلى نسخة محققة ومصدر واضح","wrong":["الاعتماد على مقطع متداول","تأليف بيت مناسب","افتراض صحة كل الروايات"],"practice":"استخرج أسلوب نداء أو صورة عاطفية من نص مقرر صحيح النسبة، مع ذكر المصدر.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":26,"title":"التنمية المستدامة","passage":"تسعى التنمية المستدامة إلى موازنة حاجات الحاضر مع قدرات الأجيال القادمة في أبعاد بيئية واجتماعية واقتصادية، وتحتاج متابعة أثر المبادرات إلى مؤشرات قابلة للقياس. مثال مستقل يستبدل فريق استهلاكًا مهدورًا بخطة إعادة استخدام ثم يسجل النتائج.","question":"ما العنصر الأساسي لتقييم مبادرة مستدامة؟","correct":"مؤشرات أثر قابلة للتحقق عبر الزمن","wrong":["الشعار وحده","افتراض النجاح","إخفاء التكاليف"],"practice":"اكتب مبادرة مدرسية صغيرة تتضمن هدفًا ومؤشرين ومراجعة للمخاطر.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"},{"cid":"49c20b78-6022-419d-bcaa-ffaa31cb886a","unit":"5b4b97a6-f9fa-410d-9d8a-1fdcab150a22","n":27,"title":"المرأة السودانية أيقونة الحياة","passage":"عنوان النص لا يكفي لنسبة قصص أو إنجازات إلى نساء سودانيات محددات دون مصادر، ولذلك يميز القارئ النص الأدبي عن تقرير واقعي. مثال مستقل يبرز دور معلمة في تشجيع القراءة بمدرستها، ولا يمثل اقتباسًا من المادة الرسمية.","question":"ما الطريقة المسؤولة لعرض إنجاز شخصية حقيقية؟","correct":"الرجوع إلى مصادر موثقة مع تحديد السياق","wrong":["اختلاق سيرة","تعميم تجربة","الاكتفاء بعبارة مدح"],"practice":"اقرأ النص المدرسي الصحيح وحدد صورته الفنية، ثم اكتب فقرة مستقلة تحترم تنوع الأدوار.","old":"DADYOOM_SD_G10_OFFICIAL_2026_V2"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='SD' AND c.id=r.cid
    AND g.grade_number=10 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'SD_G10_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'SD_G10_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'SD_G10_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'SD_G10_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_SD_G10_READING_ORIGINAL_27_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_SD_G10_READING_ORIGINAL_27_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_SD_G10_READING_ORIGINAL_27_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SD_G10_READING_ORIGINAL_27_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'SD_G10_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;